--  DDL for Trigger TG_AUD_HACO
--------------------------------------------------------

  CREATE OR REPLACE NONEDITIONABLE TRIGGER "VEI"."TG_AUD_HACO" 
AFTER UPDATE OR DELETE ON H_ACOES
FOR EACH ROW

DECLARE
    V_USU_BD VARCHAR2(30);
    V_USU_SO VARCHAR2(255) := SYS_CONTEXT('USERENV','OS_USER');
    V_TP_OPERACAO CHAR(1);
    V_TABELA VARCHAR2(30) := 'H_ACOES';

BEGIN

    SELECT USER INTO V_USU_BD
    FROM DUAL;

    IF DELETING THEN

        V_TP_OPERACAO := 'D';

        AUDITORIA.PROC_AUDITORIA(
            V_TABELA,
            V_TP_OPERACAO,
            :OLD.HACO_ID,
            'HACO_CORRETIVAS',
            :OLD.HACO_CORRETIVAS,
            NULL,
            V_USU_BD,
            V_USU_SO,
            SYSDATE
        );

    ELSE

        V_TP_OPERACAO := 'U';

        IF NVL(:OLD.HACO_CORRETIVAS,'#') <>
           NVL(:NEW.HACO_CORRETIVAS,'#') THEN

            AUDITORIA.PROC_AUDITORIA(
                V_TABELA,
                V_TP_OPERACAO,
                :OLD.HACO_ID,
                'HACO_CORRETIVAS',
                :OLD.HACO_CORRETIVAS,
                :NEW.HACO_CORRETIVAS,
                V_USU_BD,
                V_USU_SO,
                SYSDATE
            );

        END IF;

    END IF;

END;

/
